style.css:
body {
  background-color: #111; /* optional, for contrast */
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100vh;
}

img {
  width: 400px;   /* adjust size */
  border-radius: 12px;  /* rounded corners */
  box-shadow: 0 0 20px rgba(0, 255, 255, 0.5); /* glowing effect */
}
